#include <stdint.h>

//extern void initialise_monitor_handles(void);

int main(void)
{
//	initialise_monitor_handles();

	volatile uint32_t *const pClkCtrlReg = (uint32_t*) 0x40023830;

	volatile uint32_t *const pPortCModeReg = (uint32_t*) 0x40020800;
	volatile uint32_t *const pPortCOutReg = (uint32_t*) 0x40020814;

	volatile uint32_t *const pPortAModeReg = (uint32_t*) 0x40020000;
	volatile uint32_t *const pPortAPullReg = (uint32_t*) 0x4002000C;
	volatile uint32_t const *const pPortAInReg = (uint32_t*) 0x40020010;

	// Enable ABH1ENR Clock for PortA and PortC
	*pClkCtrlReg |= (1 << 0) | (1 << 2);

	// Set PC13 to OUTPUT mode
	*pPortCModeReg &= ~(3 << 26);
	*pPortCModeReg |= (1 << 26);
	// Turn OFF the c13 LED by default
	*pPortCOutReg |= (1 << 13);

	// Set PA0 to INPUT mode
	*pPortAModeReg &= ~(3 << 0);
	// Set PA0 to Pull-UP mode
	*pPortAPullReg &= ~(3 << 0);
	*pPortAPullReg |= (1 << 0);

    /* Loop forever */
	while(1){
		if(*pPortAInReg & (1 << 0))
			*pPortCOutReg |= (1 << 13);
		else
			*pPortCOutReg &= ~(1 << 13);
	}
}
